import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"FAQ & troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md","lastUpdated":1787092618000}`),a={name:`guide/faq.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="faq-troubleshooting" tabindex="-1">FAQ &amp; troubleshooting <a class="header-anchor" href="#faq-troubleshooting" aria-label="Permalink to “FAQ &amp; troubleshooting”">​</a></h1><h2 id="get-document-returned-empty-—-or-it-never-existed" tabindex="-1"><code>get_document</code> returned &quot;empty — or it never existed&quot; <a class="header-anchor" href="#get-document-returned-empty-—-or-it-never-existed" aria-label="Permalink to “get_document returned &quot;empty — or it never existed&quot;”">​</a></h2><p>That is Rustpad, not the server: <code>GET /api/text/{id}</code> answers an empty string for an empty pad, a pad that never existed, and one that expired. The three cases are indistinguishable over the API. If you expected content, the pad has most likely expired — documents are dropped after 24 hours without an open connection and on every server restart, unless the instance runs with <code>SQLITE_URI</code>.</p><h2 id="the-rustpad-websocket-connection-failed" tabindex="-1">&quot;the Rustpad WebSocket connection failed&quot; <a class="header-anchor" href="#the-rustpad-websocket-connection-failed" aria-label="Permalink to “&quot;the Rustpad WebSocket connection failed&quot;”">​</a></h2><p>The HTTP endpoints worked but the socket did not (or vice versa) — almost always a reverse-proxy issue. The proxy in front of Rustpad must forward WebSocket upgrades on <code>/api/socket/…</code>. In nginx terms: <code>proxy_set_header Upgrade $http_upgrade; proxy_set_header Connection &quot;upgrade&quot;;</code>.</p><h2 id="replace-in-document-says-the-string-occurs-n-times" tabindex="-1"><code>replace_in_document</code> says the string occurs N times <a class="header-anchor" href="#replace-in-document-says-the-string-occurs-n-times" aria-label="Permalink to “replace_in_document says the string occurs N times”">​</a></h2><p>By default the search string must match exactly once, so the model cannot accidentally rewrite more than it looked at. Either make the search string longer (include surrounding context) or pass <code>replace_all: true</code> deliberately.</p><h2 id="why-does-set-document-ask-for-a-confirm-token" tabindex="-1">Why does <code>set_document</code> ask for a confirm token? <a class="header-anchor" href="#why-does-set-document-ask-for-a-confirm-token" aria-label="Permalink to “Why does set_document ask for a confirm token?”">​</a></h2><p>Replacing a non-empty pad destroys content that cannot be restored. The first call returns a single-use token; calling again with it executes. This is deliberate friction — for targeted changes <code>replace_in_document</code> and <code>append_to_document</code> need no token, and they are also the tools that play nicely with concurrent human edits.</p><h2 id="someone-saw-rustpad-mcp-in-their-pad" tabindex="-1">Someone saw &quot;rustpad-mcp&quot; in their pad <a class="header-anchor" href="#someone-saw-rustpad-mcp-in-their-pad" aria-label="Permalink to “Someone saw &quot;rustpad-mcp&quot; in their pad”">​</a></h2><p>Working as intended: while editing, the server announces itself as a collaborator named <code>rustpad-mcp</code>, so humans in the pad can see that a machine is typing. It disconnects as soon as the tool call finishes.</p><h2 id="can-it-list-all-pads" tabindex="-1">Can it list all pads? <a class="header-anchor" href="#can-it-list-all-pads" aria-label="Permalink to “Can it list all pads?”">​</a></h2><p>No — Rustpad has no such API. Pads exist implicitly under every id; you have to know the ids you care about. <code>get_stats</code> tells you how many documents the server currently holds, but not their names.</p><h2 id="text-with-emoji-ends-up-mangled" tabindex="-1">Text with emoji ends up mangled <a class="header-anchor" href="#text-with-emoji-ends-up-mangled" aria-label="Permalink to “Text with emoji ends up mangled”">​</a></h2><p>It should not — positions are counted in Unicode code points end to end, and the test suite covers astral characters explicitly. If you can reproduce a mangling, that is a bug: please open an issue with the exact before/after text.</p>`,15)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};